// PRIMARY: beacon-chain/core/peerdas/reconstruction.go:ReconstructDataColumnSidecars (lines 31-122)
func ReconstructDataColumnSidecars(verifiedRoSidecars []blocks.VerifiedRODataColumn) ([]blocks.VerifiedRODataColumn, error) {
    // Check minimum count
    sidecarByIndex := make(map[uint64]blocks.VerifiedRODataColumn)
    for _, s := range verifiedRoSidecars { sidecarByIndex[s.Index] = s }
    sidecarCount := len(sidecarByIndex)
    if uint64(sidecarCount) < MinimumColumnCountToReconstruct() {
        return nil, ErrNotEnoughDataColumnSidecars
    }
    // Recover cells and proofs in parallel per blob
    for blobIndex := range uint64(blobCount) {
        wg.Go(func() error {
            cellsAndProofsForBlob, err := kzg.RecoverCellsAndKZGProofs(cellsIndices, cells)
            // ...
        })
    }
    // ...
}

func MinimumColumnCountToReconstruct() uint64 {
    return (params.BeaconConfig().NumberOfColumns + 1) / 2
}

// PRIMARY: beacon-chain/blockchain/kzg/kzg.go:RecoverCellsAndKZGProofs (lines 108-122)
func RecoverCellsAndKZGProofs(cellIndices []uint64, partialCells []Cell) (CellsAndProofs, error) {
    ckzgPartialCells := make([]ckzg4844.Cell, len(partialCells))
    for i := range partialCells { ckzgPartialCells[i] = ckzg4844.Cell(partialCells[i]) }
    ckzgCells, ckzgProofs, err := ckzg4844.RecoverCellsAndKZGProofs(cellIndices, ckzgPartialCells)
    if err != nil { return CellsAndProofs{}, errors.Wrap(err, "recover cells and KZG proofs") }
    return makeCellsAndProofs(ckzgCells[:], ckzgProofs[:])
}

